package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.SectorIdentifierUriVO;

class SectorIdentifierUriValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of sector identifier uri of oauth client")
  void test_sector_identifier_uri_value_holder_assign_plain_value() {
    Object holder = new Object();
    SectorIdentifierUriValueHolder<Object> value = new SectorIdentifierUriValueHolder<>(holder);
    Assertions.assertSame(holder, value.sectorIdentifierUri("one"),
        "Setters must return the holder");
    Assertions.assertTrue(value.getSectorIdentifierUriValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getSectorIdentifierUri().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.sectorIdentifierUriNull(),
        "Setters must return the holder");
    Assertions.assertTrue(value.getSectorIdentifierUriValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getSectorIdentifierUri().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of sector identifier uri of oauth client")
  void test_sector_identifier_uri_value_holder_assign_value_object() {
    Object holder = new Object();
    SectorIdentifierUriValueHolder<Object> value = new SectorIdentifierUriValueHolder<>(holder);
    SectorIdentifierUriVO vo = SectorIdentifierUriVO.from("one");
    Assertions.assertFalse(value.getSectorIdentifierUriValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.sectorIdentifierUri(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getSectorIdentifierUriValue().orElseThrow());
    Assertions.assertSame(holder, value.sectorIdentifierUri(Optional.empty()));
    Assertions.assertFalse(value.getSectorIdentifierUriValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.sectorIdentifierUri(Optional.of(vo)));
    Assertions.assertSame(vo, value.getSectorIdentifierUriValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of sector identifier uri of oauth client against the original")
  void test_sector_identifier_uri_value_holder_read() {
    Object holder = new Object();
    SectorIdentifierUriValueHolder<Object> value = new SectorIdentifierUriValueHolder<>(holder);
    SectorIdentifierUriVO vo = SectorIdentifierUriVO.from("one");
    SectorIdentifierUriVO other = SectorIdentifierUriVO.from("one");
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getSectorIdentifierUriValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readSectorIdentifierUri(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readSectorIdentifierUri(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.sectorIdentifierUri(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readSectorIdentifierUri(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readSectorIdentifierUri(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of sector identifier uri of oauth client")
  void test_sector_identifier_uri_value_holder_unset() {
    Object holder = new Object();
    SectorIdentifierUriValueHolder<Object> value = new SectorIdentifierUriValueHolder<>(holder);
    SectorIdentifierUriVO vo = SectorIdentifierUriVO.from("one");
    value.sectorIdentifierUri(vo);
    Assertions.assertSame(holder,
        value.unsetSectorIdentifierUriIfMatches("sectorIdentifierUri_other"));
    Assertions.assertTrue(value.getSectorIdentifierUriValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetSectorIdentifierUriIfMatches("sectorIdentifierUri"));
    Assertions.assertFalse(value.getSectorIdentifierUriValue().isPresent(),
        "The field name must clear the value");
    value.sectorIdentifierUri(vo);
    Assertions.assertSame(holder, value.unsetSectorIdentifierUri());
    Assertions.assertFalse(value.getSectorIdentifierUriValue().isPresent(),
        "Unset must clear the value");
  }
}
